	id_240 = { id = 240,storyId = 4,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos3",headType = 1,face = -1,facePos = -1,objectName = "地精首领",text = "我一点也不想破坏森林！但我却控制不住我自己。请快阻止我，打败我！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_241 = { id = 241,storyId = 4,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "保护森林，人人有责。既然揍你一顿还能起到保护森林的作用，我勉为其难把你打一顿。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_242 = { id = 242,storyId = 5,talkId = 1,triggerType = 1,triggerWay = {{2,1,10208}},objectType = 2,soundIndex = -1,headIndex = "common_icon_boos3",headType = 1,face = -1,facePos = -1,objectName = "地精首领",text = "谢谢你阻止了我破坏森林！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
