	id_244 = { id = 244,storyId = 5,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos3",headType = 1,face = -1,facePos = -1,objectName = "地精首领",text = "最近有一群形迹可疑的家伙向沙漠的方向走去。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_245 = { id = 245,storyId = 7,talkId = 1,triggerType = 1,triggerWay = {{1,1,10310}},objectType = 2,soundIndex = -1,headIndex = "common_icon_boos4",headType = 1,face = -1,facePos = -1,objectName = "阿努比斯祭司",text = "你来这是有什么事情要我帮你吗？只要有钱我就可以帮你。嘿嘿！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_246 = { id = 246,storyId = 7,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "谈钱多伤感情啊！不如我们来谈谈感情，能告诉我最近有没有什么形迹可疑的人来过这？",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_247 = { id = 247,storyId = 7,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos4",headType = 1,face = -1,facePos = -1,objectName = "阿努比斯祭司",text = "和你谈感情伤钱啊！不过如果愿意留下来当我的奴隶的话我就可以考虑考虑告诉你。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_248 = { id = 248,storyId = 7,talkId = 4,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "你这见钱眼开的家伙看来是不见棺材不落泪了！看看谁给谁当奴隶，看炮",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_249 = { id = 249,storyId = 8,talkId = 1,triggerType = 1,triggerWay = {{2,1,10310}},objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "看来你要给我当奴隶了，以后你的钱就是我的钱了！哈哈哈！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_250 = { id = 250,storyId = 8,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos4",headType = 1,face = -1,facePos = -1,objectName = "阿努比斯祭司",text = "（嚎叫）求求你别那么残忍啊！只要你把钱还给我，我就能告诉你想知道的，我知道你来的目的。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_251 = { id = 251,storyId = 8,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "哦！看来你知道的东西还不少，就是不知道有没有我想知道的。（一副高明的样子）",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_252 = { id = 252,storyId = 8,talkId = 4,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos4",headType = 1,face = -1,facePos = -1,objectName = "阿努比斯祭司",text = "有一群家伙来过这让我帮忙获取情报，他们好像盗取了什么圣物，要复活什么法师。我记得其中一个是小丑王。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_253 = { id = 253,storyId = 9,talkId = 1,triggerType = 1,triggerWay = {{8,1,10310}},objectType = 2,soundIndex = -1,headIndex = "common_pic_meinv2",headType = 1,face = -1,facePos = -1,objectName = "克雷•米莉亚",text = "寻找了这么久，有什么眉目吗？",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_254 = { id = 254,storyId = 9,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "小丑王好像是黑暗使者之一，圣物可能在他身上。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_255 = { id = 255,storyId = 9,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_pic_meinv2",headType = 1,face = -1,facePos = -1,objectName = "克雷•米莉亚",text = "诅咒产生的怨念不断削弱着圣树的力量，你要加紧脚步找回圣物才行。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_256 = { id = 256,storyId = 11,talkId = 1,triggerType = 1,triggerWay = {{1,1,10410}},objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "你为何要要阻挡我的道路？",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_257 = { id = 257,storyId = 11,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos5",headType = 1,face = -1,facePos = -1,objectName = "冰冷莎白",text = "你回答了我的问题我就让你过去！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
