	id_260 = { id = 260,storyId = 11,talkId = 5,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "你是世界上所有丑女之中长的最漂亮的。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_261 = { id = 261,storyId = 11,talkId = 6,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos5",headType = 1,face = -1,facePos = -1,objectName = "冰冷莎白",text = "（生气）你说什么？看我不撕烂你这张嘴。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_262 = { id = 262,storyId = 12,talkId = 1,triggerType = 1,triggerWay = {{2,1,10410}},objectType = 2,soundIndex = -1,headIndex = "common_icon_boos5",headType = 1,face = -1,facePos = -1,objectName = "冰冷莎白",text = "请手下留情放过我！我是被小丑王逼的。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
