	id_264 = { id = 264,storyId = 13,talkId = 1,triggerType = 1,triggerWay = {{1,1,10510}},objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "小丑王我知道你是黑暗使者，快把圣物交出来。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_265 = { id = 265,storyId = 13,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 2,soundIndex = -1,headIndex = "common_icon_boos6",headType = 1,face = -1,facePos = -1,objectName = "小丑王",text = "哈哈哈哈！你要我交出来就交出来，我那样不是很没有面子。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_266 = { id = 266,storyId = 13,talkId = 3,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "你不交出来，等下我会打的你更没有面子。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_267 = { id = 267,storyId = 14,talkId = 1,triggerType = 1,triggerWay = {{2,1,10510}},objectType = 2,soundIndex = -1,headIndex = "common_icon_boos6",headType = 1,face = -1,facePos = -1,objectName = "小丑王",text = "桀桀！你打败我也没用，圣物根本不在我这，它在大摩斯那！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_268 = { id = 268,storyId = 14,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "（叹气）嗨！看来拯救世界果然没有那么容易！",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
