	id_270 = { id = 270,storyId = 15,talkId = 1,triggerType = 1,triggerWay = {{8,1,10510}},objectType = 2,soundIndex = -1,headIndex = "common_pic_meinv2",headType = 1,face = -1,facePos = -1,objectName = "克雷•米莉亚",text = "在小丑王那里夺回圣物了么?",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
	id_271 = { id = 271,storyId = 15,talkId = 2,triggerType = 1,triggerWay = -1,objectType = 1,soundIndex = -1,headIndex = -1,headType = 1,face = -1,facePos = -1,objectName = -1,text = "诶！没有！圣物在他的同伙暗黑大摩斯那里。",buttonName = -1,buttonJump = -1,count = 1,isjump = 1},
